def transform(grid):
    h, w = len(grid), len(grid[0])
    # Diagonal seed strokes encode a repeating diagonal stripe word. Infer the
    # period from consistent colored anti-diagonals, preserving blank phases.
    by_diag = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c]:
                by_diag.setdefault(r + c, set()).add(grid[r][c])
    labels = {d: next(iter(vs)) for d, vs in by_diag.items() if len(vs) == 1}
    # Repeat the complete two-dimensional diagonal motif with its observed
    # phase; source strokes encode diagonal bands and overlap by priority.
    period = 5
    phases = {d % period: color for d, color in labels.items()}
    word = [phases.get(i, 0) for i in range(period)]
    return [[word[(r + c) % period] for c in range(w)] for r in range(h)]

